import{_ as a,c as s,o as e,a4 as n}from"./chunks/framework.D5y910bP.js";const h=JSON.parse('{"title":"Upload/Download from S3 CLI (rclone)","description":"","frontmatter":{"date":"2023-10-23T00:00:00.000Z","tags":["s3","script","aws","cloudflare","r2","rclone","gist"],"title":"Upload/Download from S3 CLI (rclone)"},"headers":[],"relativePath":"blog/s3-upload-download-rclone.md","filePath":"blog/s3-upload-download-rclone.md","lastUpdated":1739289997000}'),l={name:"blog/s3-upload-download-rclone.md"},t=n(`<h1 id="upload-download-from-s3-cli-rclone" tabindex="-1">Upload/Download from S3 CLI (rclone) <a class="header-anchor" href="#upload-download-from-s3-cli-rclone" aria-label="Permalink to &quot;Upload/Download from S3 CLI (rclone)&quot;">​</a></h1><p><a href="https://rclone.org/" target="_blank" rel="noreferrer">rclone</a> is a command line program to manage files on cloud storage. It supports many cloud storage providers like Google Drive, Amazon S3, Dropbox, etc.</p><p>It is one of the most useful tools I have used.</p><p>Here is a simple script to upload and download files from s3/r2 bucket.</p><p>Usage -</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./s3.sh &lt;file_path&gt; &lt;bucket&gt; &lt;method&gt; &lt;prefix&gt;</span></span>
<span class="line"><span>PUT Example: ./s3.sh path/to/file bucket-name PUT prefix/</span></span>
<span class="line"><span>Will upload file path/to/file to s3://bucket-name/prefix/path/to/file</span></span>
<span class="line"><span>GET Example: ./s3.sh path/to/file bucket-name GET prefix/</span></span>
<span class="line"><span>Will download file from s3://bucket-name/prefix/path/to/file to path/to/file</span></span>
<span class="line"><span>Note: prefix is optional</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><ul><li>Requires rclone binary in path. (apt-get install rclone)</li><li>Requires rclone config named s3conn or the following environment variables</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RCLONE_CONFIG_S3CONN_TYPE=s3</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_PROVIDER=AWS</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ENV_AUTH=false</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_REGION=us-east-1</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ENDPOINT=</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ACCESS_KEY_ID=XXXX</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_SECRET_ACCESS_KEY=XXXX</span></span></code></pre></div></div><details class="details custom-block"><summary>For Cloudflare</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RCLONE_CONFIG_S3CONN_TYPE=s3</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_PROVIDER=Cloudflare</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ENV_AUTH=false</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_REGION=auth</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ENDPOINT=https://&lt;ACCOUNT_ID&gt;.r2.cloudflarestorage.com</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_ACCESS_KEY_ID=XXXX</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_SECRET_ACCESS_KEY=XXXX</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_no_head_object=true</span></span>
<span class="line"><span>RCLONE_CONFIG_S3CONN_no_list_bucket=true</span></span></code></pre></div><p><a href="https://developers.cloudflare.com/r2/api/s3/api/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/r2/api/s3/api/</a></p></details><p>Code on <a href="https://gist.github.com/repalash/cff71a73127b1a65075adba7677af7d6" target="_blank" rel="noreferrer">Github Gist</a> -</p><iframe width="100%" height="350" src="data:text/html;charset=utf-8,&lt;head&gt;&lt;base target=&#39;_blank&#39;/&gt;&lt;/head&gt;&lt;body&gt;&lt;script src=&#39;https://cors-proxy.r2cache.com/https://gist.github.com/repalash/cff71a73127b1a65075adba7677af7d6.js&#39;&gt;&lt;/script&gt;&lt;/body&gt;"></iframe>`,10),p=[t];function o(i,r,c,d,_,N){return e(),s("div",null,p)}const u=a(l,[["render",o]]);export{h as __pageData,u as default};
